tool_calls.command:
cat > /tmp/tier_test.go <<'EOF'
package mcp

import (
	"fmt"
	"testing"

	"github.com/crier-dev/crier/internal/registry"
)

func TestTierArithmetic(t *testing.T) {
	n := New(registry.NewMemoryStore()).ToolCount()
	for _, tc := range []struct{ name, id, http, mesh string }{
		{"tier0", "", "", ""},
		{"tier1", "mcp-agent", "", ""},
		{"tier2", "mcp-agent", "http://localhost:8767", ""},
		{"tier3", "mcp-agent", "http://localhost:8767", "ws://localhost:8767/mesh/connect/mcp-agent"},
	} {
		u, m := UnavailableTools(tc.id, tc.http, tc.mesh)
		fmt.Printf("%s: tools=%d available=%d unavailable=%v missing=%v\n", tc.name, n, n-len(u), u, m)
	}
}
EOF
cp /tmp/tier_test.go internal/mcp/zz_tier_test.go && go test ./internal/mcp/ -run TestTierArithmetic -v -count=1 2>&1 | head -20; rm internal/mcp/zz_tier_test.go
